-- EventPass Supabase setup + data import (generated for SQL Editor)
BEGIN;

-- Ensure scan_log/admin_audit exist
CREATE TABLE IF NOT EXISTS scan_log (
    id BIGSERIAL PRIMARY KEY,
    ts TEXT NOT NULL,
    code TEXT NOT NULL,
    result TEXT NOT NULL,
    gate TEXT
);

CREATE TABLE IF NOT EXISTS admin_audit (
    id BIGSERIAL PRIMARY KEY,
    ts TEXT NOT NULL,
    action TEXT NOT NULL,
    code TEXT NOT NULL,
    detail TEXT
);

CREATE INDEX IF NOT EXISTS scan_log_ts_idx ON scan_log(ts);
CREATE INDEX IF NOT EXISTS scan_log_gate_idx ON scan_log(gate);

-- Ensure passes has the correct schema for EventPass (recreate if mismatched)
DO $$
DECLARE
    cols text;
BEGIN
    SELECT string_agg(column_name, ',' ORDER BY ordinal_position) INTO cols
    FROM information_schema.columns
    WHERE table_schema='public' AND table_name='passes';

    IF cols IS NOT NULL AND cols <> 'serial,code,used,used_at,gate,revoked' THEN
        EXECUTE 'DROP TABLE passes';
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS passes (
    serial BIGSERIAL PRIMARY KEY,
    code TEXT UNIQUE NOT NULL,
    used INTEGER NOT NULL DEFAULT 0,
    used_at TEXT,
    gate TEXT,
    revoked INTEGER NOT NULL DEFAULT 0
);

