-- Import admin_audit
-- (no admin_audit rows)

-- Reset sequences
SELECT setval(pg_get_serial_sequence('passes','serial'), COALESCE((SELECT MAX(serial) FROM passes), 1), true);
SELECT setval(pg_get_serial_sequence('scan_log','id'), COALESCE((SELECT MAX(id) FROM scan_log), 1), true);
SELECT setval(pg_get_serial_sequence('admin_audit','id'), COALESCE((SELECT MAX(id) FROM admin_audit), 1), true);

-- Verify
SELECT COUNT(*) AS passes_count FROM passes;
SELECT COUNT(*) AS scan_log_count FROM scan_log;
SELECT COUNT(*) AS admin_audit_count FROM admin_audit;
SELECT COUNT(*) AS total, COALESCE(SUM(CASE WHEN used=1 AND revoked=0 THEN 1 ELSE 0 END),0) AS entered FROM passes;

COMMIT;
